(function($) {
    $.fn.sticky = function(options) {
        var settings = $.extend({
            top: 0,
            bottom: 0,
            stopOn: null,
            disableOn: 0
        }, options);

        return this.each(function() {
            var $this = $(this);
            var $window = $(window);
            var $stopEl = settings.stopOn ? $(settings.stopOn) : null;
            var initialOffset = $this.offset() ? $this.offset().top : 0;
            var initialPosition = $this.css('position');
            var initialTop = $this.css('top');

            function checkSticky() {
                var windowWidth = $window.width();
                if (settings.disableOn && windowWidth < settings.disableOn) {
                    $this.css({ position: '', top: '', width: '' });
                    return;
                }

                var scrollTop = $window.scrollTop();
                var triggerTop = initialOffset - settings.top;

                if (scrollTop > triggerTop) {
                    var parentWidth = $this.parent().width();
                    var newTop = settings.top;

                    if ($stopEl && $stopEl.length) {
                        var stopTop = $stopEl.offset().top;
                        var elementHeight = $this.outerHeight();
                        if (scrollTop + settings.top + elementHeight + settings.bottom > stopTop) {
                            newTop = stopTop - (scrollTop + elementHeight + settings.bottom) + settings.top;
                        }
                    }

                    $this.css({
                        position: 'fixed',
                        top: newTop + 'px',
                        width: parentWidth + 'px',
                        zIndex: 99
                    });
                } else {
                    $this.css({
                        position: initialPosition,
                        top: initialTop,
                        width: ''
                    });
                }
            }

            $window.on('scroll resize', checkSticky);
            checkSticky();
        });
    };
})(jQuery);
